19	// formatMarker identifies the on-disk file format version.
20	const formatMarker = "edgefleet-heartbeats-v1"
21	
22	// onlineWindow is the maximum age of the latest telemetry for a node to be
23	// considered online. Exactly onlineWindow is still online.
24	const onlineWindow = 60 * time.Second
25	
26	// CorruptError means the on-disk data failed parsing or verification. The
27	// store refuses to read or write while corruption is present.
28	type CorruptError struct {
29		Path string
30		Err  error
31	}
32	
33	func (e *CorruptError) Error() string {
34		return fmt.Sprintf("data corruption detected in %s: %v", e.Path, e.Err)
35	}
36	
37	func (e *CorruptError) Unwrap() error { return e.Err }
38	
39	// IsCorrupt reports whether err is (or wraps) a CorruptError.
40	func IsCorrupt(err error) bool {
41		var ce *CorruptError
42		return errors.As(err, &ce)
43	}
44	
45	// nodeFile is the on-disk layout for one node.
46	type nodeFile struct {
47		Format   string      `json:"format"`
48		Checksum string      `json:"checksum"`
49		Records  []Heartbeat `json:"records"`
50	}
51	
52	// Store persists heartbeats as per-node JSON files under a data directory.
53	// Multiple Store instances (in the same or different processes) may safely
54	// access the same directory concurrently: a flock on the directory lock file
55	// serialises writers and lets queries take a shared lock, so a query never
56	// observes a partially written batch.
57	//
58	// Node files live in two places chosen solely by the byte length of the node
59	// id:
60	//
61	//   - Short ids keep their file at nodes/hex(nodeID)+".json", exactly as
62	//     always; the file name itself decodes to the owning node id.
63	//   - Long ids (those whose hex name would exceed the local file-name limit)
64	//     keep their file at slots/<sha256(nodeID)>.json: a fixed-length content
65	//     name that never grows with the id. The hash is computed over the whole
66	//     id and only addresses the file — it never identifies the node — so a
67	//     slot is loaded for a specific queried id and every record in it must
68	//     declare that same id, the same ownership check a named hex file gets.
69	//     A different id whose well-formed file is found at this slot (a planted
70	//     foreign file) is refused as corruption rather than merged or read as
71	//     this node's telemetry.
72	type Store struct {
73		dir      string
74		nodesDir string
75		slotsDir string
76		lockPath string
77	}
78	
79	// OpenStore opens (and if needed creates) a data directory.
80	func OpenStore(dir string) (*Store, error) {
81		if err := os.MkdirAll(dir, 0o755); err != nil {
82			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
83		}
84		nodesDir := filepath.Join(dir, "nodes")
85		if err := os.MkdirAll(nodesDir, 0o755); err != nil {
86			return nil, fmt.Errorf("cannot create nodes directory %s: %w", nodesDir, err)
87		}
88		slotsDir := filepath.Join(dir, "slots")
89		if err := os.MkdirAll(slotsDir, 0o755); err != nil {
90			return nil, fmt.Errorf("cannot create slots directory %s: %w", slotsDir, err)
91		}
92		return &Store{
93			dir:      dir,
94			nodesDir: nodesDir,
95			slotsDir: slotsDir,
96			lockPath: filepath.Join(dir, "lock"),
97		}, nil
98	}
99	
100	// Dir returns the data directory path.
101	func (s *Store) Dir() string { return s.dir }
102	
103	// maxNodeFileNameBytes is the local file-system name limit the store targets:
104	// the base name of a short-id file is two hex characters per id byte plus the
105	// ".json" suffix, and may use the full limit — every such name was writable
106	// before long-id support existed, and keeping the limit at exactly this value
107	// means every id that previously saved still uses its original file (no
108	// rename, move or resubmit). Ids whose hex name would exceed the limit use a
109	// fixed-length slot name instead; the limit never rejects an id — it only
110	// selects where the file is placed.
111	const maxNodeFileNameBytes = 255
112	
113	// nodeLocation is the one on-disk file holding one node's records.
114	type nodeLocation struct {
115		path  string
116		owner string // the node id every record in the file must declare
117		named bool   // true: a legacy hex file whose name carries its owner; false: a hash-addressed slot whose owner is the queried id
118	}
119	
120	// nodeLocationFor maps a node id to its storage location. The mapping depends
121	// only on the exact id bytes — no trimming, whitespace handling or character
122	// replacement — so two ids are stored apart unless their bytes are identical:
123	// ids sharing a long prefix and differing at the end hash differently, and an
124	// id submitted literally or via equivalent JSON escapes decodes to the same
125	// bytes and maps to the same file. A short id's file name is its own hex,
126	// which reversibly carries its owner; a long id's slot name is the full hash
127	// of its bytes and carries no id text at all, so its owner is the queried id
128	// itself.
129	func (s *Store) nodeLocationFor(nodeID string) nodeLocation {
130		raw := []byte(nodeID)
131		hexName := hex.EncodeToString(raw) + ".json"
132		if len(hexName) <= maxNodeFileNameBytes {
133			return nodeLocation{
134				path:  filepath.Join(s.nodesDir, hexName),
135				owner: nodeID,
136				named: true,
137			}
138		}
139		sum := sha256.Sum256(raw)
140		return nodeLocation{
141			path:  filepath.Join(s.slotsDir, hex.EncodeToString(sum[:])+".json"),
142			owner: nodeID,
143		}
144	}
145	
146	// nodePath maps a node id to its per-node file. Short ids use a reversible hex
147	// file name; ids too long for a file name use a fixed-length content-addressed
148	// slot, so arbitrary-length legal Unicode ids never depend on a file name
149	// being able to hold them.
150	func (s *Store) nodePath(nodeID string) string {
151		return s.nodeLocationFor(nodeID).path
152	}
153	
154	// nodeOwnerFromPath recovers the node id a *short-id* store file belongs to
155	// from its file name: short-id files are named hex(nodeID)+".json", so the
156	// owner is exactly the string the base name decodes to. Slot file names are
157	// hashes that carry no node id; their owner is supplied by the caller (the id
158	// being queried), not inferred from the name.
159	func nodeOwnerFromPath(path string) (string, error) {
160		base := filepath.Base(path)
161		if !strings.HasSuffix(base, ".json") {
162			return "", fmt.Errorf("file name %q is not a per-node heartbeat file", base)
163		}
164		raw, err := hex.DecodeString(strings.TrimSuffix(base, ".json"))
165		if err != nil {
166			return "", fmt.Errorf("file name %q does not encode a node id: %w", base, err)
167		}
168		return string(raw), nil
169	}
170	
171	// lock acquires the directory lock. Exclusive for writes, shared for reads.
172	// The returned closure releases the lock.
173	func (s *Store) lock(exclusive bool) (func(), error) {
174		f, err := os.OpenFile(s.lockPath, os.O_RDWR|os.O_CREATE, 0o600)
175		if err != nil {
176			return nil, fmt.Errorf("cannot open lock file %s: %w", s.lockPath, err)
177		}
178		how := syscall.LOCK_SH
179		if exclusive {
180			how = syscall.LOCK_EX
181		}
182		if err := syscall.Flock(int(f.Fd()), how); err != nil {
183			f.Close()
184			return nil, fmt.Errorf("cannot acquire data lock: %w", err)
185		}
186		return func() {
187			syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
188			f.Close()
189		}, nil
190	}
191	
192	// checksumRecords returns a stable hash of the records. json.Marshal of a
193	// struct slice is deterministic for a given set of records.
194	func checksumRecords(records []Heartbeat) string {
195		data, _ := json.Marshal(records)
196		sum := sha256.Sum256(data)
197		return hex.EncodeToString(sum[:])
198	}
199	
200	// loadNodeFile reads and verifies the file at loc. A missing file means the
201	// node has no records (returns nil, nil). Any parse, checksum, ownership
202	// or structural failure is reported as a CorruptError.
203	//
204	// Ownership: the file belongs to exactly one node — loc.owner — and every
205	// record in it must declare that same node id. A file whose records name
206	// another node (for example another node's file copied over this one, format
207	// and checksum still intact) is not that node's telemetry: the whole file is
208	// refused as corrupt, no matter where the foreign record sits in the history
209	// and even if the latest record happens to name the right node.
210	//
211	// The two storage layouts prove ownership differently but enforce the exact
212	// same rule. A legacy file under nodes/ is named hex(owner), so its owner is
213	// decoded from the file name itself; that decoded id must also equal the id
214	// being queried. A slot file under slots/ has a hash for a name that reveals
215	// no node id, so its owner is the exact id whose slot this is — the full text
216	// the user queried or submitted, never a truncated or normalised form.
217	// Copying another node's complete file into a slot therefore fails just as
218	// copying it onto a legacy file name does.
219	//
220	// The file is decoded with the same strict rules as submit input: every
221	// telemetry field must be present, non-null and written once per record. A
222	// checksum that matches the zero-filled interpretation of a tampered record
223	// therefore cannot make a missing value look like real telemetry — the
224	// record is rejected before the checksum is consulted.
225	func loadNodeFile(loc nodeLocation) (*nodeFile, error) {
226		path := loc.path
227		data, err := os.ReadFile(path)
228		if os.IsNotExist(err) {
229			return nil, nil
230		}
231		if err != nil {
232			return nil, &CorruptError{Path: path, Err: err}
233		}
234		nf, err := decodeStrictNodeFile(data)
235		if err != nil {
236			return nil, &CorruptError{Path: path, Err: err}
237		}
238		if nf.Format != formatMarker {
239			return nil, &CorruptError{Path: path, Err: fmt.Errorf("unknown format marker %q", nf.Format)}
240		}
241		if err := validateStoredRecords(nf.Records); err != nil {
242			return nil, &CorruptError{Path: path, Err: err}
243		}
244		if got := checksumRecords(nf.Records); got != nf.Checksum {
245			return nil, &CorruptError{Path: path, Err: fmt.Errorf("checksum mismatch: stored %s, computed %s", nf.Checksum, got)}
246		}
247		owner := loc.owner
248		if loc.named {
249			namedOwner, err := nodeOwnerFromPath(path)
250			if err != nil {
251				return nil, &CorruptError{Path: path, Err: err}
252			}
253			// The queried id and the file name must name the same owner.
254			if namedOwner != owner {
255				return nil, &CorruptError{Path: path, Err: fmt.Errorf(
256					"file name encodes node %q, but it was loaded for node %q",
257					namedOwner, owner)}
258			}
259		}
260		for i, r := range nf.Records {
261			if r.NodeID != owner {
262				return nil, &CorruptError{Path: path, Err: fmt.Errorf(
263					"record %d: heartbeat declares node %q, but this file belongs to node %q",
264					i+1, r.NodeID, owner)}
265			}
266		}
267		return nf, nil
268	}
269	
270	// decodeStrictNodeFile parses the on-disk envelope without letting
271	// encoding/json defaults hide missing or duplicated data. The envelope has
272	// exactly three keys — format, checksum, records — each present, non-null and
273	// written once; the uniqueness judgement is the shared objectFields rule, so
274	// a Unicode-escaped spelling of the same key collides exactly as it does in a
275	// submitted heartbeat object. Every element of records is decoded with
276	// decodeStrictHeartbeatObject, so a missing, null or duplicated telemetry
277	// field is an error naming the record and field rather than a zero value.
278	// Whitespace and key ordering carry no meaning and never cause a failure.
279	func decodeStrictNodeFile(data []byte) (*nodeFile, error) {
280		dec := json.NewDecoder(bytes.NewReader(data))
281		tok, err := dec.Token()
282		if err != nil {
283			return nil, fmt.Errorf("invalid JSON: %w", err)
284		}
285		if d, ok := tok.(json.Delim); !ok || d != '{' {
286			return nil, fmt.Errorf("invalid JSON: file must be a JSON object")
287		}
288	
289		var (
290			format   string
291			checksum string
292			records  []json.RawMessage
293		)
294		fields := objectFields{}
295		for dec.More() {
296			keyTok, err := dec.Token()
297			if err != nil {
298				return nil, fmt.Errorf("invalid JSON: %w", err)
299			}
300			key, ok := keyTok.(string)
301			if !ok {
302				return nil, fmt.Errorf("invalid JSON: envelope field name must be a string")
303			}
304			var val json.RawMessage
305			if err := dec.Decode(&val); err != nil {
306				return nil, fmt.Errorf("invalid value for envelope field %q: %w", key, err)
307			}
308			if fields.check(key) {
309				return nil, fmt.Errorf("duplicate envelope field %q", key)
310			}
311			switch key {
312			case "format":
313				if bytes.Equal(val, []byte("null")) {
314					return nil, fmt.Errorf("envelope field %q must not be null", key)
315				}
316				if err := json.Unmarshal(val, &format); err != nil {
317					return nil, fmt.Errorf("format must be a string: %w", err)
318				}
319			case "checksum":
320				if bytes.Equal(val, []byte("null")) {
321					return nil, fmt.Errorf("envelope field %q must not be null", key)
322				}
323				if err := json.Unmarshal(val, &checksum); err != nil {
324					return nil, fmt.Errorf("checksum must be a string: %w", err)
325				}
326			case "records":
327				if bytes.Equal(val, []byte("null")) {
328					return nil, fmt.Errorf("envelope field %q must not be null", key)
329				}
330				if err := json.Unmarshal(val, &records); err != nil {
331					return nil, fmt.Errorf("records must be an array of heartbeat objects: %w", err)
332				}
333			default:
334				return nil, fmt.Errorf("unknown envelope field %q", key)
335			}
336		}
337		// Consume the closing brace.
338		if _, err := dec.Token(); err != nil {
339			return nil, fmt.Errorf("invalid JSON: %w", err)
340		}
341		// Nothing may follow the single envelope object.
342		if _, err := dec.Token(); err != io.EOF {
343			if err == nil {
344				return nil, fmt.Errorf("invalid JSON: unexpected data after the envelope object")
345			}
346			return nil, fmt.Errorf("invalid JSON: %w", err)
347		}
348	
349		if !fields.has("format") {
350			return nil, fmt.Errorf("missing required envelope field %q", "format")
351		}
352		if !fields.has("checksum") {
353			return nil, fmt.Errorf("missing required envelope field %q", "checksum")
354		}
355		if !fields.has("records") {
356			return nil, fmt.Errorf("missing required envelope field %q", "records")
357		}
358	
359		nf := &nodeFile{Format: format, Checksum: checksum, Records: make([]Heartbeat, 0, len(records))}
360		for i, raw := range records {
361			h, err := decodeStrictHeartbeatObject(raw)
362			if err != nil {
363				return nil, fmt.Errorf("record %d: %w", i+1, err)
364			}
365			nf.Records = append(nf.Records, h)
366		}
367		return nf, nil
368	}
369	
370	// validateStoredRecords checks the structural invariants of a strictly
371	// decoded record set: each record must satisfy the same field-value rules as
372	// submit input (one shared rule set — see checkHeartbeatValues), and records
373	// must be sorted by ascending seq with no duplicate seq. The stored-data
374	// wording and 1-based position prefix are kept by storedError. Position
375	// numbers are 1-based to match decoder errors.
376	func validateStoredRecords(records []Heartbeat) error {
377		for i, r := range records {
378			if e := checkHeartbeatValues(r); e != nil {
379				return e.storedError(i + 1)
380			}
381			if i > 0 && records[i-1].Seq >= r.Seq {
382				return fmt.Errorf("records not sorted by ascending seq at record %d", i+1)
383			}
384		}
385		return nil
386	}
387	
388	// writeNodeFile persists records atomically: a temp file in the same
389	// directory is fsynced and renamed over the target, so a crash never leaves
390	// a half-written file.
391	//
392	// It is a package-level function variable rather than a plain func only so the
393	// persist stage can be deterministically failed from tests that exercise a
394	// real, mid-batch persistence failure (some node files already renamed into
395	// place before the failing one); production code always invokes the default
396	// implementation below and never reassigns it.
397	var writeNodeFile = func(path string, records []Heartbeat) error {
398		if records == nil {
399			records = []Heartbeat{}
400		}
401		nf := nodeFile{
402			Format:   formatMarker,
403			Checksum: checksumRecords(records),
404			Records:  records,
405		}
406		data, err := json.MarshalIndent(nf, "", "  ")
407		if err != nil {
408			return err
409		}
410		return writeFileAtomic(path, data)
411	}
412	
413	func writeFileAtomic(path string, data []byte) error {
414		dir := filepath.Dir(path)
415		tmp, err := os.CreateTemp(dir, ".tmp-*")
416		if err != nil {
417			return err
418		}
419		tmpName := tmp.Name()
420		if _, err := tmp.Write(data); err != nil {
421			tmp.Close()
422			os.Remove(tmpName)
423			return err
424		}
425		if err := tmp.Sync(); err != nil {
426			tmp.Close()
427			os.Remove(tmpName)
428			return err
429		}
430		if err := tmp.Close(); err != nil {
431			os.Remove(tmpName)
432			return err
433		}
434		if err := os.Rename(tmpName, path); err != nil {
435			os.Remove(tmpName)
436			return err
437		}
438		// Best-effort fsync of the directory so the rename itself survives.
439		if d, err := os.Open(dir); err == nil {
440			d.Sync()
441			d.Close()
442		}
443		return nil
444	}
445	
446	// mergeRecord applies the single dedup/conflict rule shared by both submit
447	// phases (records within the batch, and the batch against stored history): a
448	// record's identity is its node id and seq together, and known must contain
449	// only records of that same node. If known already holds the identity, the
450	// incoming record is a duplicate when Heartbeat.Equal says the content is
451	// identical — collection time compared as an instant, node id and version
452	// compared as-is — and a conflict when any field differs. A conflict is an
453	// error naming the node and seq and changes nothing; a duplicate leaves
454	// known untouched and reports dup. Otherwise the record is appended and
455	// returned in the updated slice.
456	func mergeRecord(known []Heartbeat, r Heartbeat) (updated []Heartbeat, dup bool, err error) {
457		for _, e := range known {
458			if e.Seq == r.Seq {
459				if !e.Equal(r) {
460					return nil, false, fmt.Errorf("conflicting record for node %q seq %d: content differs", r.NodeID, r.Seq)
461				}
462				return known, true, nil
463			}
464		}
465		return append(known, r), false, nil
466	}
467	
468	// Submit persists a batch of heartbeats. The whole batch is validated and
469	// checked for duplicates/conflicts against stored data (and within the batch)
470	// before anything is written: a single invalid or conflicting record fails
471	// the batch with no changes. Duplicates are counted, not written, and a node
472	// whose records are all duplicates of its saved history is not re-saved at
473	// all — only nodes that actually gained records are persisted. A
474	// successful return means the batch was durably persisted; a persistence
475	// failure is reported and previously queryable data is left intact.
476	func (s *Store) Submit(records []Heartbeat, receiveTime time.Time) (newCount, dupCount int, err error) {
477		if len(records) == 0 {
478			return 0, 0, fmt.Errorf("no heartbeat records provided")
479		}
480		for _, r := range records {
481			if err := ValidateHeartbeat(r, receiveTime); err != nil {
482				return 0, 0, fmt.Errorf("invalid heartbeat for node %q seq %d: %w", r.NodeID, r.Seq, err)
483			}
484		}
485	
486		unlock, err := s.lock(true)
487		if err != nil {
488			return 0, 0, err
489		}
490		defer unlock()
491	
492		// Deduplicate within the batch: same node+seq with equal content counts
493		// as a duplicate; same node+seq with differing content is a conflict.
494		merged := make(map[string][]Heartbeat)
495		for _, r := range records {
496			list, dup, err := mergeRecord(merged[r.NodeID], r)
497			if err != nil {
498				return 0, 0, err
499			}
500			if dup {
501				dupCount++
502				continue
503			}
504			merged[r.NodeID] = list
505		}
506	
507		// Merge with stored data per node, collecting new file contents. Every
508		// node's stored history is still loaded and checked (corruption or a
509		// conflict rejects the whole batch before anything is written), but a
510		// node whose records are all duplicates of what is already saved gains
511		// no record, so its file is left untouched: re-saving identical content
512		// would only turn a harmless retransmit into a write failure when the
513		// file's directory cannot be created or replaced.
514		type update struct {
515			loc     nodeLocation
516			records []Heartbeat
517		}
518		var updates []update
519		for nodeID, batch := range merged {
520			loc := s.nodeLocationFor(nodeID)
521			nf, err := loadNodeFile(loc)
522			if err != nil {
523				return 0, 0, err
524			}
525			existing := []Heartbeat{}
526			if nf != nil {
527				existing = nf.Records
528			}
529			nodeNew := 0
530			for _, r := range batch {
531				var dup bool
532				existing, dup, err = mergeRecord(existing, r)
533				if err != nil {
534					return 0, 0, err
535				}
536				if dup {
537					dupCount++
538				} else {
539					newCount++
540					nodeNew++
541				}
542			}
543			if nodeNew == 0 {
544				continue
545			}
546			sort.Slice(existing, func(i, j int) bool { return existing[i].Seq < existing[j].Seq })
547			updates = append(updates, update{loc: loc, records: existing})
548		}
549	
550		// Persist. All updates are appends to previously verified data, so a
551		// failure here leaves every previously queryable record intact.
552		for _, u := range updates {
553			if err := writeNodeFile(u.loc.path, u.records); err != nil {
554				return 0, 0, fmt.Errorf("failed to persist heartbeat batch: %w", err)
555			}
556		}
557		return newCount, dupCount, nil
558	}
559	
560	// HealthResult is the health judgement for one node based on real telemetry.
561	type HealthResult struct {
562		NodeID      string
563		Status      string // "online", "offline", "notelemetry"
564		Seq         int64
565		CollectedAt time.Time
566		Version     string
567		Height      int64
568		Missed      int64 // cumulative missed duties at the latest heartbeat
569		Findings    []string
570	
571		// Baseline-relative missed duties, populated only by HealthSince.
572		// BaselineSeq is the seq of the heartbeat the query was anchored to;
573		// BaselineMissed is the cumulative count at that heartbeat. When
574		// NewMissedKnown is false the cumulative counter went backwards
575		// somewhere between the baseline and the latest record, so the number of
576		// newly missed duties cannot be derived; Findings then reports the
577		// rollback. Missed always remains the latest cumulative count.
578		BaselineSeq    int64
579		BaselineMissed int64
580		NewMissed      int64
581		NewMissedKnown bool
582	}
583	
584	// rollbackFinding warns that the cumulative missed-duty counter decreased
585	// between two adjacent saved heartbeats (typically a node counter reset),
586	// which makes the endpoint difference unusable as the new-miss count.
587	const rollbackFinding = "累计漏签数回退"
588	
589	// Health judges a node from its latest telemetry (the record with the
590	// greatest seq). A node with no heartbeats returns Status "notelemetry". A
591	// query time earlier than the record's collection time is an error. Online
592	// status uses collection age against the query time: at most 60s is online
593	// (exactly 60s still online). Version skew and missed-duty rules follow the
594	// existing Evaluate rules.
595	func (s *Store) Health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int) (HealthResult, error) {
596		return s.health(nodeID, at, expectedVersion, toleratedMisses, 0, false)
597	}
598	
599	// HealthSince judges a node the same way Health does, but the missed-duty
600	// alarm is measured against a user-supplied baseline heartbeat instead of the
601	// cumulative counter alone. baselineSeq must be the seq (> 0) of a record
602	// already saved for the node: the latest heartbeat stays the record with the
603	// greatest seq, and new missed duties are the latest cumulative count minus
604	// the count at the baseline record. Only a strict excess over
605	// toleratedMisses alarms; equality does not.
606	//
607	// The baseline affects this query only: stored history is never modified.
608	// Seqs between the baseline and the latest may have gaps. If the cumulative
609	// count decreases between any two adjacent saved records in that interval the
610	// new count is reported as unknown (NewMissedKnown == false) and a rollback
611	// finding is emitted, even if the latest count later climbs back past the
612	// baseline; decreases before the baseline are irrelevant. A node without
613	// telemetry, an unknown baseline seq, or a baseline newer than the latest
614	// record is an error — no other record is substituted and the baseline count
615	// is never assumed to be zero.
616	func (s *Store) HealthSince(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64) (HealthResult, error) {
617		if baselineSeq <= 0 {
618			return HealthResult{}, fmt.Errorf("--missed-since-seq must be a positive integer, got %d", baselineSeq)
619		}
620		return s.health(nodeID, at, expectedVersion, toleratedMisses, baselineSeq, true)
621	}
622	
623	func (s *Store) health(nodeID string, at time.Time, expectedVersion string, toleratedMisses int, baselineSeq int64, useBaseline bool) (HealthResult, error) {
624		unlock, err := s.lock(false)
625		if err != nil {
626			return HealthResult{}, err
627		}
628		defer unlock()
629	
630		nf, err := loadNodeFile(s.nodeLocationFor(nodeID))
631		if err != nil {
632			return HealthResult{}, err
633		}
634		if nf == nil || len(nf.Records) == 0 {
635			if useBaseline {
636				return HealthResult{}, fmt.Errorf("node %q has no heartbeats; cannot use --missed-since-seq=%d as baseline", nodeID, baselineSeq)
637			}
638			return HealthResult{NodeID: nodeID, Status: "notelemetry", Findings: []string{"无遥测"}}, nil
639		}
640	
641		records := nf.Records // ascending seq, unique
642		latest := records[len(records)-1]
643	
644		if useBaseline {
645			if baselineSeq > latest.Seq {
646				return HealthResult{}, fmt.Errorf("--missed-since-seq=%d is newer than the latest heartbeat seq %d for node %q", baselineSeq, latest.Seq, nodeID)
647			}
648		}
649	
650		if at.Before(latest.CollectedAt) {
651			return HealthResult{}, fmt.Errorf("query time %s is earlier than collection time %s for node %q",
652				at.Format(time.RFC3339), latest.CollectedAt.Format(time.RFC3339), nodeID)
653		}
654	
655		age := at.Sub(latest.CollectedAt)
656		online := age <= onlineWindow
657	
658		result := HealthResult{
659			NodeID:      nodeID,
660			Status:      "online",
661			Seq:         latest.Seq,
662			CollectedAt: latest.CollectedAt,
663			Version:     latest.Version,
664			Height:      latest.Height,
665			Missed:      latest.Missed,
666		}
667		if !online {
668			result.Status = "offline"
669		}
670	
671		if !useBaseline {
672			// Cumulative judgement: the current counter must strictly exceed the
673			// tolerance. Evaluate holds this rule — and the shared online/version
674			// rules — in exactly one place for the demo and both query paths.
675			node := Node{
676				ID:      nodeID,
677				Version: latest.Version,
678				Height:  latest.Height,
679				Missed:  int(latest.Missed),
680				Online:  online,
681			}
682			result.Findings = Evaluate(node, expectedVersion, toleratedMisses).Findings
683			return result, nil
684		}
685	
686		// Baseline judgement: the online and version-skew findings come from the
687		// same shared rules as the cumulative query above; only the missed-duty
688		// statistic differs — it counts duties missed after the baseline record
689		// instead of the latest cumulative total.
690		findings := append([]string{}, livenessVersionFindings(online, latest.Version, expectedVersion)...)
691	
692		baselineIdx := -1
693		for i, r := range records {
694			if r.Seq == baselineSeq {
695				baselineIdx = i
696				break
697			}
698		}
699		if baselineIdx < 0 {
700			return HealthResult{}, fmt.Errorf("no saved heartbeat with seq %d for node %q; cannot use it as --missed-since-seq baseline", baselineSeq, nodeID)
701		}
702		baseline := records[baselineIdx]
703		result.BaselineSeq = baseline.Seq
704		result.BaselineMissed = baseline.Missed
705	
706		// Walk only saved records from the baseline up to the latest. Records are
707		// stored ascending by seq and seqs may legitimately have gaps, so any
708		// decrease between two adjacent saved records in this interval proves the
709		// cumulative counter reset somewhere in it; the endpoint difference alone
710		// must not be trusted even if the final count recovers.
711		rolledBack := false
712		for i := baselineIdx + 1; i < len(records); i++ {
713			if records[i].Missed < records[i-1].Missed {
714				rolledBack = true
715				break
716			}
717		}
718		if rolledBack {
719			result.NewMissedKnown = false
720			findings = append(findings, rollbackFinding)
721		} else {
722			result.NewMissedKnown = true
723			// No decrease was observed, so cumulative counts cannot have wrapped
724			// backwards within int64 range; the difference stays exact.
725			result.NewMissed = latest.Missed - baseline.Missed
726			if result.NewMissed > int64(toleratedMisses) {
727				findings = append(findings, missedAboveToleranceFinding)
728			}
729		}
730		result.Findings = findings
731		return result, nil
732	}
733	
734	// History returns all heartbeats for a node in ascending seq order, without
735	// duplicates. A node with no records returns an empty slice.
736	func (s *Store) History(nodeID string) ([]Heartbeat, error) {
737		unlock, err := s.lock(false)
738		if err != nil {
739			return nil, err
740		}
741		defer unlock()
742	
743		nf, err := loadNodeFile(s.nodeLocationFor(nodeID))
744		if err != nil {
745			return nil, err
746		}
747		if nf == nil {
748			return []Heartbeat{}, nil
749		}
750		return nf.Records, nil
751	}
