47	// defaultDataDir resolves the data directory: --data-dir flag, then the
48	// EDGEFLEET_DATA_DIR environment variable, then ~/.edgefleet.
49	func defaultDataDir() string {
50		if d := os.Getenv("EDGEFLEET_DATA_DIR"); d != "" {
51			return d
52		}
53		home, err := os.UserHomeDir()
54		if err != nil {
55			return ".edgefleet"
56		}
